"""Heavier differential tester: many runs per batch, tight caps, deep branches."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
import ref as refmod
from adapter import execute_batch


def random_partition(U, count):
    if U <= 1:
        return [0, U]
    inner = sorted(random.sample(range(1, U), min(count, U - 1)))
    return [0] + inner + [U]


def make_run():
    M = random.randint(1, 5)
    L = random.randint(1, 3)
    U = random.choice([1, 2, 3, 12, 40, 2147483647])
    R = random.randint(1, min(6, max(1, U - 1))) if U > 1 else 1
    borders = random_partition(U, R)
    kind = random.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = list(range(random.randint(1, 4)))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, random.choice([0, 1, max(0, U - 1), U + 7, 2147483647]) if U else 0] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, random.randint(1, 1024)] for f in flows]}
    else:
        policy = {'kind': kind}
    tight = random.random() < 0.5
    spec = {'banks': M, 'load_balancers': L,
            'fifo_bytes': random.choice([1, 2, 6, 30, 10 ** 6]) if tight else random.randint(1, 200),
            'pifo_bytes': random.choice([1, 2, 6, 30, 10 ** 6]) if tight else random.randint(1, 200),
            'refill_batch': random.choice([1, 2, 3, 32]),
            'sample_period': random.choice([1, 1, 2, 5, 97]),
            'borders': borders, 'policy': policy, 'events': []}
    n = random.randint(0, 140)
    next_id = 0
    names = []
    for _ in range(n):
        choice = random.random()
        if choice < 0.40:
            spec['events'].append(['enqueue', next_id, random.choice(flows),
                                   random.choice([1, 1, 2, 3, 7, 50, 1000000]),
                                   random.choice([0, 1, 2, max(0, U // 2), U, U + 5, 2147483647])])
            next_id += 1
        elif choice < 0.58:
            spec['events'].append(['dequeue', random.randint(1, 6)])
        elif choice < 0.63:
            spec['events'].append(['sample'])
        elif choice < 0.70:
            spec['events'].append(['repartition', random_partition(U, random.randint(1, min(7, max(1, U - 1))))])
        elif choice < 0.76:
            spec['events'].append(['cancel', random.randrange(0, max(next_id + 3, 4))])
        elif choice < 0.82:
            spec['events'].append(['inspect', random.randrange(0, max(next_id + 3, 4))])
        elif choice < 0.86 and kind == 'wfq':
            spec['events'].append(['weight', random.choice(flows), random.randint(1, 1024)])
        elif choice < 0.93:
            name = random.randrange(0, 4)
            spec['events'].append(['save', name])
            names.append(name)
        else:
            if names:
                spec['events'].append(['restore', random.choice(names)])
            else:
                spec['events'].append(['inspect', 0])
    return spec


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    for seed in range(lo, hi):
        random.seed(seed)
        runs = [make_run() for _ in range(random.randint(1, 3))]
        request = {'runs': runs}
        mine = json.loads(json.dumps(execute_batch(request)))
        theirs = json.loads(json.dumps(refmod.run_batch(request)))
        if mine != theirs:
            print('SEED', seed, 'MISMATCH')
            json.dump(request, open('/workspace/dev/fail2_%d.json' % seed, 'w'))
            for k, (a, b) in enumerate(zip(mine['runs'], theirs['runs'])):
                if a != b:
                    la, lb = a['log'], b['log']
                    for j in range(min(len(la), len(lb))):
                        if la[j] != lb[j]:
                            print(' run', k, 'row', j, '\n  engine:', la[j], '\n  ref   :', lb[j])
                            break
                    else:
                        print(' run', k, 'log len', len(la), len(lb))
                        print('  engine state', json.dumps(a['state'])[:600])
                        print('  ref    state', json.dumps(b['state'])[:600])
                    break
            return 1
    print('checked', hi - lo, 'batches')
    return 0


if __name__ == '__main__':
    sys.exit(main())
